    (v_lesson, 'gaps', replace($blk${"title": "Давай теперь потренируемся! Вставь have got / haven't got / has got / hasn't got", "mode": "drag", "text": "1. Mary __has got__ a car, but she __hasn't got__ a motorbike.\n2. John and Mary __have got__ blue eyes and dark hair, they are twins.\n3. Samantha __hasn't got__ a cat, but she __has got__ a dog, she is a dog lover.\n4. My sisters __have got__ dark hair.\n5. My mother __has got__ a small head and big ears.\n6. Alex __hasn't got__ a big face, his face is small.\n7. Trevor __hasn't got__ a mobile phone, he sends emails."}$blk$, '@@MEDIA@@', v_media)::jsonb, 8),
