    (v_lesson, 'task', replace($blk${"title": "Что есть у Molly и Nick?", "needs_review": true, "html": "<p><img src=\"@@MEDIA@@gg1/u4/venn_have_got.webp\" alt=\"Have got: Nick and Molly\" style=\"max-width:100%\"></p><p>Посмотри на картинку и напиши предложения о том, что есть у Molly и Nick. Подсказка: используй have got / has got.</p><ol><li>What has Molly got?</li><li>What has Nick got?</li><li>What have they got?</li></ol>"}$blk$, '@@MEDIA@@', v_media)::jsonb, 15),
    (v_lesson, 'speaking', replace($blk${"title": "Мой рюкзак 🎤", "html": "<p>Нажми на микрофон и ответь на вопрос: <b>What have you got in your school bag today?</b></p><p><i>Пример: I've got two books, a pencil case and a bottle of water.</i></p>", "needs_review": true}$blk$, '@@MEDIA@@', v_media)::jsonb, 16),
